import {slots,subKeys,maxLevel,mainKeys,mainValue,rolls,artifactIssues,applyMain,addRoll} from './artifact-rules.mjs';
import {energyBudget} from './energy.mjs';
import {setupBuilder} from './builder.mjs?v=7';
import {mediaMarkup,hydrateMedia,findMedia,normalizeName,resolveName} from './media.mjs?v=4';
import {defaults,character,weapons,statNames,buff} from './data.mjs?v=7';
import {calc,effective,stats} from './engine.mjs?v=7';
let state;try{state=JSON.parse(localStorage.getItem('stygian-lab-v1'));if(!state||state.version!==1)state=defaults()}catch{state=defaults()}
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,d=0)=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:d}):'—', short=n=>n>=1e6?(n/1e6).toFixed(2)+'m':n>=1000?(n/1000).toFixed(1)+'k':num(n), team=()=>state.teams[state.selected],char=()=>team().chars[state.member];
let timer;function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function persist(){try{localStorage.setItem('stygian-lab-v1',JSON.stringify(state));return true}catch{toast('Browser storage is unavailable. Export a backup to keep your edits.');return false}}
function field(label,path,value,opts={}){return `<label class="field ${opts.full?'full':''}">${esc(label)}${opts.options?`<select data-path="${path}">${Object.entries(opts.options).map(([v,l])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input data-path="${path}" type="${opts.text?'text':'number'}" value="${esc(value)}" ${opts.text?'':`step="${opts.step??'any'}" min="${opts.min??0}" ${opts.max!==undefined?`max="${opts.max}"`:''}`} ${opts.title?`title="${esc(opts.title)}"`:''}>`}</label>`}
const cp=k=>`teams.${state.selected}.chars.${state.member}.${k}`,tp=k=>`teams.${state.selected}.${k}`,f=(l,k,o={})=>field(l,cp(k),char()[k],o),tf=(l,k,o={})=>field(l,tp(k),team()[k],o),range=(prefix,a,b)=>Object.fromEntries(Array.from({length:b-a+1},(_,i)=>[i+a,prefix+(i+a)]));
function artifactCard(c){const split=c.setMode==='split';return `<span class="card-artifacts"><span class="artifact-mode">${split?'2pc + 2pc':'4pc'}</span><span class="set-line">${mediaMarkup('artifacts',c.set,'mini')}<span>${esc(c.set||'Choose a set')}</span></span>${split?`<span class="set-line">${c.set2?mediaMarkup('artifacts',c.set2,'mini'):'<span class="set-placeholder">+</span>'}<span>${esc(c.set2||'Choose second set')}</span></span>`:''}</span>`}
function render(){const t=team(),c=char(),r=calc(t),all=state.teams.map(calc),time=all.every(x=>x.time!==null)?all.reduce((n,x)=>n+x.time,0):null,ref=state.teams.reduce((n,x)=>n+x.reference,0);$('#app').innerHTML=`<header><div class="brand"><span class="mark">✧</span><div>STYGIAN<small>DAMAGE LAB</small></div></div><div class="top-actions"><button data-library>Saved teams</button><button data-do="import">Import</button><button data-do="export">Export build ↗</button></div></header><main class="shell"><section class="hero"><div><div class="eyebrow">Genshin Impact / Personal theorycrafting</div><h1>Three teams. <em>One goal.</em></h1><p>Fine-tune every build. Make every second count.</p></div><div class="season">STYGIAN PURSUIT<br><strong>October 14, 2026</strong><br>Ranking 78,999 · user reference</div></section><section class="overview"><div class="goal"><small>YOUR STYGIAN TARGET</small><div class="value">210–218 <span>seconds</span></div><small>Battle 1 + Battle 2 + Battle 3</small></div><div><small>REFERENCE CLEAR TOTAL</small><div class="value">${num(ref,1)} <span>seconds</span></div><div class="mini-track">${state.teams.map(x=>`<i style="width:${x.reference/ref*100}%"></i>`).join('')}</div><small>73–81s / 64s / 73s</small></div><div><small>MODEL CLEAR ESTIMATE</small><div class="value">${time===null?'—':num(time,1)} <span>seconds</span></div><small class="warn">Illustrative until your inputs are verified</small></div></section><section class="team-toolbar"><div><h2>Your team workspace</h2><p>Name a battle, open a saved build, or compare up to three teams.</p></div><div class="button-row"><button data-library>Open saved teams (${(state.savedTeams||[]).length})</button><button class="primary" data-compare>Compare teams</button></div></section><nav class="battle-tabs" aria-label="Battle">${state.teams.map((x,i)=>`<button class="battle ${state.selected===i?'active':''}" data-battle="${i}" aria-pressed="${state.selected===i}"><span class="num">0${i+1}</span><div><strong>${esc(x.title)}</strong><small>${esc(x.subtitle)}</small></div><span class="time">${x.refLow===x.refHigh?x.refLow:x.refLow+'–'+x.refHigh}s ↗</span></button>`).join('')}</nav><div class="team-name-row">${state.teams.map((x,i)=>field(`Battle ${i+1} team name`,`teams.${i}.title`,x.title,{text:true})).join('')}</div><div class="workspace"><div><div class="notice"><strong>Build your baseline.</strong> Team names and equipment match your notes. Stats, attack multipliers, enemy HP and rotations are example inputs. Buffs start off. Levels, talents, C/R and set names are recorded; enter their actual numeric effects below.</div><div class="section-top"><div><h2>Battle 0${state.selected+1} <span class="muted">/</span> ${esc(t.title)}</h2><p>Select a slot, then choose any character and equipment.</p><div class="button-row"><button data-picker="characters">Browse characters</button><button data-library>Save / load team</button></div></div><span class="chip">4 characters · saved on this browser</span></div><div class="members">${t.chars.map((x,i)=>`<button class="member ${state.member===i?'active':''}" data-member="${i}" aria-pressed="${state.member===i}"><span class="member-portrait">${mediaMarkup('characters',x.name)}<span class="element-dot ${esc(x.element)}">${({Anemo:'≋',Cryo:'❄',Pyro:'♨',Electro:'ϟ',Hydro:'≈',Dendro:'❧',Geo:'◇'})[x.element]}</span></span><span class="cons">C${x.cons} / R${x.refine}</span><span class="member-copy"><strong>${esc(x.name)}</strong><small>${esc(x.element)} · Lv. ${x.level}</small></span><span class="card-equipment"><span class="member-weapon">${mediaMarkup('weapons',x.weapon,'mini')}<span>${esc(x.weapon)}<small>Lv. ${x.weaponLevel} · R${x.refine}</small></span></span>${artifactCard(x)}</span></button>`).join('')}</div><nav class="tabs" aria-label="Calculator section">${Object.entries({build:'Character & weapon',artifacts:'Artifacts',buffs:'Team buffs',rotation:'Damage & rotation',energy:'Energy',enemy:'Enemy & goal',sources:'Sources & model'}).map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}" aria-pressed="${state.tab===id}">${label}</button>`).join('')}</nav><section id="editor">${({build:build,artifacts:artifacts,buffs:buffs,rotation:rotation,energy:energyPanel,enemy:enemy,sources:sources}[state.tab]||build)()}</section></div><aside class="aside"><section class="panel"><div class="section-top"><span class="eyebrow">Live calculation</span><span class="chip">AVERAGE</span></div><div class="big">${short(r.total)}</div><small>team damage / ${num(t.rotation)}s rotation</small><dl><dt>Team DPS</dt><dd>${short(r.dps)}</dd><dt>Estimated battle clear</dt><dd>${r.time===null?'—':num(r.time,1)+'s'}</dd><dt>Reference midpoint</dt><dd>${num(t.reference,1)}s</dd><dt>Active buffs</dt><dd>${t.buffs.filter(x=>x.enabled).length} / ${t.buffs.length}</dd></dl><div class="divider"></div><h3>Damage contribution</h3>${r.members.map((m,i)=>`<div class="bar-row"><div><span>${esc(t.chars[i].name)}</span><span>${r.total?num(m.total/r.total*100,1):0}%</span></div><div class="bar"><i style="width:${r.total?m.total/r.total*100:0}%"></i></div></div>`).join('')}<p class="inline-note">Average CRIT-weighted damage. No automatic aura, cooldown, energy, shield, or boss-phase simulation.</p><button class="primary" style="width:100%" data-do="snapshot">Save comparison baseline</button>${state.snapshot?`<div class="divider"></div><small>Against saved Battle 0${state.snapshot.battle+1} · ${esc(state.snapshot.name)}</small><p><strong class="good">${state.snapshot.battle===state.selected?(state.snapshot.damage>0?num((r.total/state.snapshot.damage-1)*100,1)+'% damage change':'Baseline was zero damage'):'Switch to that battle to compare'}</strong></p><button class="quiet" data-do="restore">Restore baseline build</button>`:''}</section><section class="panel"><h3>${esc(c.name)} · effective stats</h3>${effectiveStats()}<div class="divider"></div><h3>Reference runs</h3>${t.links.map((id,i)=>`<a class="source" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">Watch Battle ${state.selected+1}${t.links.length>1?' · Run '+(i+1):''} ↗</a>`).join('')}<p class="inline-note">Times supplied by you. Video builds were not extracted.</p></section></aside></div><footer class="footer"><span>STYGIAN / A personal build workbench · Unofficial fan tool</span><span>Formula references: KQM · Last researched October 18, 2026</span></footer></main>`;void hydrateMedia()}
function effectiveStats(){const {s}=effective(char(),team(),state.member);return `<dl>${Object.entries({atk:'ATK',hp:'HP',def:'DEF',em:'Elemental mastery',cr:'CRIT rate',cd:'CRIT damage',er:'Energy recharge',dmg:'Ordinary DMG bonus'}).map(([k,l])=>`<dt>${l}</dt><dd>${num(s[k],1)}${['cr','cd','er','dmg'].includes(k)?'%':''}</dd>`).join('')}</dl>`}
function build(){const c=char();return `<div class="panel"><div class="build-identity">${mediaMarkup('characters',c.name,'large')}<div><span class="eyebrow">Selected character</span><h2>${esc(c.name)}</h2><p>${esc(c.element)} · Level ${c.level} · C${c.cons}</p></div></div><div class="row-head"><h3>Character details</h3><button data-picker="characters">Change character</button>${state.member===3&&state.selected<2?`<button data-do="alternate">Switch to ${c.name==='Sucrose'?(state.selected===0?'Faruzan':'Qiqi'):'Sucrose'} ⇄</button>`:''}</div><div class="grid">${f('Character','name',{text:true})}${f('Element','element',{options:Object.fromEntries(['Anemo','Cryo','Pyro','Electro','Hydro','Dendro','Geo'].map(x=>[x,x]))})}${f('Character level','level',{min:1,max:100,step:1})}${f('Constellation','cons',{options:range('C',0,6)})}${f('Base ATK at current level','baseAtk')}${f('Base HP at current level','baseHp')}${f('Base DEF at current level','baseDef')}${f('Normal attack talent','talentN',{min:1,max:15,step:1})}${f('Skill talent','talentE',{min:1,max:15,step:1})}${f('Burst talent','talentQ',{min:1,max:15,step:1})}</div><p class="inline-note">Use base stats at the selected level and ascension. Talent levels and constellation are build records; set exact attack coefficients in Damage & rotation and constellation buffs in Team buffs.</p></div><div class="panel"><div class="build-identity">${mediaMarkup('weapons',c.weapon,'large')}<div><span class="eyebrow">Equipped weapon</span><h2>${esc(c.weapon)}</h2><p>Level ${c.weaponLevel} · Refinement ${c.refine}</p></div></div><div class="grid"><div class="full button-row"><button data-picker="weapons">Browse weapons</button></div>${f('Weapon name','weapon',{text:true,full:true})}${f('Weapon level','weaponLevel',{min:1,max:90,step:1})}${f('Refinement','refine',{options:range('R',1,5)})}${f('Base weapon ATK','weaponAtk')}${f('Secondary stat','weaponStat',{options:statNames})}${f('Secondary stat value','weaponValue')}</div><div class="button-row"><button data-do="weapon">Load known level-90 weapon stats</button>${state.selected===0&&state.member===0?'<button data-do="echoes">Equip Echoes of the Heart</button>':''}</div><p class="inline-note">Weapon passives and refinement effects are explicit buff inputs, not automatic. “Silver” was ambiguous in your notes; enter its full weapon name and stats if using it. Aquila’s Physical DMG does not apply to Bennett’s Pyro actions.</p></div><div class="panel"><h3>Ascension, innate stats & manual adjustments</h3><p>These add to base + weapon + artifacts. Do not paste total character-sheet values here.</p><div class="grid">${f('ATK % adjustment','atkPct')}${f('Flat ATK adjustment','atkFlat')}${f('HP % adjustment','hpPct')}${f('DEF % adjustment','defPct')}${f('Innate / extra EM','em')}${f('Base + ascension CRIT rate %','cr',{max:100})}${f('Base + ascension CRIT damage %','cd')}${f('Extra ER % (above 100%)','er')}${f('Ordinary DMG bonus %','dmg')}${f('Stellar reaction bonus %','stellar')}${f('Stellar base DMG bonus %','stellarBase')}${f('Stellar elevation %','elevation')}</div><p class="inline-note">For mixed-element actions, calculate separate configurations. Ordinary elemental bonuses never increase Stellar damage.</p>${f('Build notes','notes',{text:true,full:true})}</div>`}
function artifacts(){const c=char();return `<div class="panel"><h3>Artifact loadout</h3><div class="button-row"><button data-picker="artifacts" data-slot="set">Choose first set</button>${c.setMode==='split'?'<button data-picker="artifacts" data-slot="set2">Choose second set</button>':''}</div><div class="grid two">${field('Set configuration',cp('setMode'),c.setMode||'four',{options:{four:'4-piece set',split:'2-piece + 2-piece combo'}})}${f(c.setMode==='split'?'First 2-piece set':'4-piece set','set',{text:true})}${c.setMode==='split'?field('Second 2-piece set',cp('set2'),c.set2||'',{text:true}):''}</div><div class="artifact-loadout-preview">${artifactCard(c)}</div><p>Main stats depend on slot, rarity and level. Substats cannot repeat the main stat or each other. HP and HP % are different stats. Set bonuses remain in Team buffs.</p><p>Each +4 levels adds a substat until four are present, then upgrades one. Enter the actual rolled total or add a legal roll below. Raising the level updates only the main stat; it does not invent random upgrades.</p></div>${c.artifacts.map((a,i)=>{const issues=artifactIssues(a,i),mainOptions=Object.fromEntries(mainKeys(i).map(k=>[k,statNames[k]]));if(!mainOptions[a.main.stat])mainOptions[a.main.stat]=(statNames[a.main.stat]||a.main.stat)+' · legacy invalid';return `<div class="panel artifact"><div class="row-head"><h3>${['✿','➶','⌛','♜','♛'][i]} ${slots[i]}</h3><span class="chip">PIECE 0${i+1}</span></div><div class="grid">${field('Rarity',cp(`artifacts.${i}.rarity`),a.rarity||5,{options:{3:'3★',4:'4★',5:'5★'}})}${field('Artifact level',cp(`artifacts.${i}.level`),a.level,{min:0,max:maxLevel(a.rarity||5),step:1})}${field('Main stat',cp(`artifacts.${i}.main.stat`),a.main.stat,{options:mainOptions})}<label class="field">Main stat value<input readonly aria-label="Main stat value" value="${num(a.main.value,1)}"></label></div><button data-main-table="${i}">Apply level table</button>${issues.length?`<div class="notice" role="status">${issues.map(esc).join(' ')} Existing values are kept until you edit them.</div>`:''}<div class="grid two">${a.subs.map((sub,j)=>{const allowed=subKeys.filter(k=>k!==a.main.stat&&!a.subs.some((x,n)=>n!==j&&x.stat===k&&x.value>0));const options=Object.fromEntries(allowed.map(k=>[k,statNames[k]]));if(!options[sub.stat])options[sub.stat]=(statNames[sub.stat]||sub.stat)+' · invalid';return `<div class="sub-editor"><div class="sub-row">${field('Substat '+(j+1),cp(`artifacts.${i}.subs.${j}.stat`),sub.stat,{options})}${field('Total value',cp(`artifacts.${i}.subs.${j}.value`),sub.value,{max:Math.max(...rolls(a,sub.stat),0)*(1+Math.floor(a.level/4))})}</div><small>Legal single rolls: ${rolls(a,sub.stat).map(v=>num(v,2)).join(' / ')}</small><div class="roll-buttons">${rolls(a,sub.stat).map((v,k)=>`<button title="Add one ${num(v,2)} roll" data-add-roll="${i},${j},${k}">+${num(v,2)}</button>`).join('')}<button data-clear-sub="${i},${j}">Clear</button></div></div>`}).join('')}</div><small>Up to ${Math.min(4,(a.rarity||5)-1)+Math.floor(a.level/4)} total rolls at this rarity and level. Zero means an unused substat.</small></div>`}).join('')}`}

const buffNames={atkPct:'ATK %',atkFlat:'Flat ATK',em:'EM',cr:'CRIT rate %',cd:'CRIT damage %',dmg:'Ordinary DMG %',stellar:'Stellar bonus %',base:'Stellar base bonus %',elevation:'Stellar elevation %',shred:'RES shred %',defShred:'DEF reduction %',defIgnore:'DEF ignore %'};
function buffs(){const t=team();return `<div class="panel"><h3>Make the buff state explicit</h3><p>Enable only effects that are active for the selected damage window. Each row applies independently; duplicate set buffs must not be stacked. For exact snapshot or timed windows, use 0% or 100% uptime and calculate windows separately.</p><p>Partial uptime linearly averages the buff’s stat value, so it is an approximation. Numeric values do not auto-update when C/R or equipment changes. On-field-only buffs should target one character.</p><div class="button-row"><button data-do="buffadd">+ Custom buff</button><button data-do="buffoff">Disable all</button></div></div>${t.buffs.map((b,i)=>`<div class="panel buff"><input aria-label="Enable ${esc(b.label)}" type="checkbox" data-check="${tp(`buffs.${i}.enabled`)}" ${b.enabled?'checked':''}><div><div class="row-head"><strong>${esc(b.label)}</strong><button aria-label="Remove ${esc(b.label)}" data-remove-buff="${i}">×</button></div>${field('Buff name',tp(`buffs.${i}.label`),b.label,{text:true})}<div class="grid">${field('Effect',tp(`buffs.${i}.stat`),b.stat,{options:buffNames})}${field('Value',tp(`buffs.${i}.value`),b.value,{min:-10000})}${field('Target',tp(`buffs.${i}.target`),b.target,{options:{all:'Whole team',...Object.fromEntries(t.chars.map((c,j)=>[j,c.name]))}})}${field('Element filter',tp(`buffs.${i}.element`),b.element,{options:Object.fromEntries(['all','Anemo','Cryo','Pyro','Electro','Hydro','Dendro','Geo'].map(x=>[x,x==='all'?'All elements':x]))})}${field('Uptime %',tp(`buffs.${i}.uptime`),b.uptime,{max:100})}</div><small>${esc(b.condition)}</small></div></div>`).join('')}`}
const modes={normal:'Ordinary talent damage',melt:'Forward Melt · Pyro ×2',reverseMelt:'Reverse Melt · Cryo ×1.5',vape:'Reverse Vaporize · Pyro ×1.5',forwardVape:'Forward Vaporize · Hydro ×2',ssc:'Direct Stellar-Conduct',ssw:'Direct Stellar Swirl',swirl:'Ordinary Swirl · no CRIT'};
function rotation(){const c=char(),t=team(),r=calc(t);return `<div class="panel"><h3>Rotation settings</h3><div class="grid">${tf('Rotation length (seconds)','rotation',{min:1})}${tf('Extra damage / rotation (manual)','extraDamage')}${tf('Polestar application stacks','stacks',{max:12,step:1})}</div><p>Extra damage is already-mitigated average damage, added once per rotation. Use it for independently calculated reaction Stellar Swirl: the shared multi-contributor vortex is not simulated here. Do not also count that damage in character actions.</p><p>Polestar stacks affect direct Stellar-Conduct only. Split reacted and unreacted hits into separate rows; “8 Melt hits” means all eight hits Melt.</p></div>${c.actions.map((a,i)=>`<div class="panel"><div class="row-head"><h3>Action 0${i+1} · ${esc(c.name)}</h3><button data-remove-action="${i}">Remove</button></div><div class="grid">${field('Attack / hit group',cp(`actions.${i}.name`),a.name,{text:true,full:true})}${field('Damage mode',cp(`actions.${i}.mode`),a.mode,{options:modes})}${field('Scaling stat',cp(`actions.${i}.scaling`),a.scaling,{options:{atk:'ATK',hp:'HP',def:'DEF',em:'EM'}})}${field('Talent coefficient %',cp(`actions.${i}.mult`),a.mult)}${field('Hits per rotation',cp(`actions.${i}.hits`),a.hits,{step:1})}${field('Additive base damage',cp(`actions.${i}.flat`),a.flat)}${field('Attack DMG bonus % (ordinary)','bonus' in a?cp(`actions.${i}.bonus`):'',a.bonus)}${field('Reaction bonus % (Melt / Vape / Swirl)',cp(`actions.${i}.reactionBonus`),a.reactionBonus)}</div><div class="divider"></div><div class="metric-strip"><span>Non-CRIT<strong>${short(r.members[state.member].rows[i].normal)}</strong></span><span>CRIT<strong>${short(r.members[state.member].rows[i].crit)}</strong></span><span>Average / hit<strong>${short(r.members[state.member].rows[i].avg)}</strong></span><span>Rotation total<strong>${short(r.members[state.member].rows[i].total)}</strong></span></div></div>`).join('')}<button data-do="actionadd">+ Add attack group</button><div class="panel" style="margin-top:16px"><h3>Full team damage breakdown</h3><div class="table-wrap"><table><thead><tr><th>Character / action</th><th>Hits</th><th>Average hit</th><th>Total</th></tr></thead><tbody>${t.chars.map((ch,j)=>ch.actions.map((a,i)=>`<tr><td>${esc(ch.name)} · ${esc(a.name)}</td><td>${a.hits}</td><td>${num(r.members[j].rows[i].avg)}</td><td>${num(r.members[j].rows[i].total)}</td></tr>`).join('')).join('')}</tbody></table></div></div>`}
function enemy(){return `${bossPanel()}<div class="panel"><h3>Enemy assumptions</h3><div class="grid">${tf('Enemy level','enemyLevel',{min:1,max:200,step:1})}${tf('Enemy HP (enter boss value)','hp',{min:1})}${tf('Base resistance %','res',{min:-100,max:1000})}${tf('Downtime / transitions (seconds)','downtime')}${tf('Reference clear time (seconds)','reference',{min:1})}${field('Combined target ceiling (seconds)','goal',state.goal,{min:1})}${tf('Ordinary Swirl level multiplier','levelMultiplier')}</div><p>Resistance applies to each character’s selected damage element. Use separate configurations for enemies with different elemental resistances. Ordinary Swirl uses this explicit level multiplier, not an interpolated character-level curve. At level 90 the reference is approximately 1446.85.</p><p>Clear time = enemy HP ÷ rotation-average DPS + downtime. It does not predict immunity windows, shield checks, overkill, energy availability, or stagger. Reference runs are independent of this model.</p></div><div class="panel"><h3>Three-battle plan</h3><div class="table-wrap"><table><thead><tr><th>Battle</th><th>Reference</th><th>Model</th><th>Target DPS*</th></tr></thead><tbody>${state.teams.map((t,i)=>{const r=calc(t);return `<tr><td>0${i+1} · ${esc(t.title)}</td><td>${t.reference}s</td><td>${r.time?num(r.time,1)+'s':'—'}</td><td>${t.reference>t.downtime?short(t.hp/(t.reference-t.downtime)):'—'}</td></tr>`}).join('')}</tbody></table></div><p>*Required DPS for the supplied reference time, using your current enemy HP and downtime.</p><p>Target ceiling: <strong>${state.goal}s.</strong> ${state.teams.every(t=>calc(t).time!==null)?`Model is ${num(Math.abs(state.teams.reduce((n,t)=>n+calc(t).time,0)-state.goal),1)}s ${state.teams.reduce((n,t)=>n+calc(t).time,0)>state.goal?'over':'under'} that ceiling.`:'Add nonzero damage to every battle to estimate the total.'}</p></div>`}
function sources(){return `<div class="panel"><h3>Transparent calculations</h3><p>This is a configurable damage workbench, not a complete combat simulator or an Akasha leaderboard replica. Every result depends on the stats, coefficients, buffs, and hit counts you enter.</p><details open><summary>Ordinary damage</summary><p>(Scaling stat × talent coefficient + additive damage) × (1 + ordinary DMG bonus) × DEF multiplier × RES multiplier × reaction multiplier × CRIT factor.</p></details><details><summary>Stellar damage</summary><p>Direct Stellar modes use their own base bonus, EM scaling, reaction bonus and elevation. They ignore enemy DEF and ordinary DMG bonuses. Direct Stellar-Conduct uses the selected Polestar multiplier; direct Stellar Swirl uses 1. Shared reaction Stellar Swirl must be entered as separately calculated extra damage.</p></details><details><summary>What is automatic?</summary><p>Artifact stat totals, weapon secondary stat, explicit buffs, CRIT expectation, reaction math, resistance, defense, hit totals, rotation DPS and HP-based clear estimates. Level, constellation, refinement, talent levels and equipment names are records: their progression tables and passive triggers are not automatically modeled. Artifact level edits use verified main-stat tables; substats are checked against legal roll values. Set exact coefficients and passive effects manually. No hidden C/R multipliers.</p></details><details><summary>Buffs, energy and rotations</summary><p>Buff eligibility is your responsibility. Changing a teammate disables all buffs so effects from the previous team cannot remain active accidentally. Duplicate buffs are additive; enable only one copy of nonstacking sets. The Energy tab starts at zero and estimates the entered opening energy budget. It does not simulate event timing or automatically remove infeasible burst damage. Favonius procs and boss drops are separate inputs. Nightsoul, Fighting Spirit, ICD, reaction ownership and Witch’s Revelation unlocks require manual inputs.</p></details><details><summary>Data and saving</summary><p>Your edits are stored in this browser only. Export JSON for a portable backup, and import it on another device. Save comparison baseline retains one complete battle build locally. Example statistics are not extracted from the videos or from your account.</p></details></div><div class="panel"><h3>Research & references</h3><a class="source" href="https://github.com/theBowja/genshin-db" target="_blank" rel="noopener">Genshin DB · Character & weapon artwork ↗<small>Name-matched API metadata with artwork from HoYoverse. Team images are bundled locally; other exact names are looked up on demand. Cryo Traveler uses Aether’s portrait. Artwork © HoYoverse.</small></a>${[['https://library.keqingmains.com/combat-mechanics/damage/damage-formula','KQM Theorycrafting Library','Standard damage, DEF, resistance and reaction formulas.'],['https://feelcrafting.com/misc/stellar/','Stellar Glimmer Reaction Guide','Direct Stellar modes, Polestar field and shared reaction distinctions.'],['https://keqingmains.com/misc/snezhnaya/','KQM · Version 7.0 overview','New equipment and Stellar set effects.'],['https://keqingmains.com/q/sandrone-quickguide/','KQM · Sandrone','Build and rotation context; see source for conditions.'],['https://keqingmains.com/q/mizuki-quickguide/','KQM · Mizuki','Build and team context.'],['https://keqingmains.com/q/mavuika-quickguide/','KQM · Mavuika','Build and team context.'],['https://www.stygian.moe/','Stygian.moe · Boss data','Current season name, boss HP and phase mechanics; this app uses a dated snapshot, not a live API.'],['https://library.keqingmains.com/combat-mechanics/energy','KQM · Energy mechanics','Particle, orb, Favonius, on-field and off-field energy values.'],['https://akasha.cv/','Akasha','External build comparison. No account data is imported here.']].map(([url,title,desc])=>`<a class="source" href="${url}" target="_blank" rel="noopener">${title} ↗<small>${desc}</small></a>`).join('')}</div><div class="panel"><h3>Start over</h3><p>Export a backup before resetting all three teams.</p><button data-do="reset">Reset to supplied team presets</button></div>`}
function setPath(path,value){let parts=path.split('.'),o=state;for(const p of parts.slice(0,-1))o=o[p];o[parts.at(-1)]=value}
document.addEventListener('input',e=>{const path=e.target.dataset.path;if(!path||!['set','set2'].includes(path.split('.').at(-1)))return;setPath(path,e.target.value);persist();const card=document.querySelector(`.member[data-member="${state.member}"] .card-artifacts`);if(card)card.outerHTML=artifactCard(char());const summary=document.querySelector('.artifact-loadout-preview');if(summary)summary.innerHTML=artifactCard(char());void hydrateMedia()});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.path){let v=el.value;if(el.type==='number'){v=Number(v);if(!Number.isFinite(v)||!el.validity.valid){toast('Enter a number within the field’s allowed range.');render();return}}const path=el.dataset.path;const key=path.split('.').at(-1);if(['cons','refine'].includes(key))v=Number(v);if(path.endsWith('.title')){v=String(v).trim().slice(0,80);if(!v){toast('Enter a team name.');render();return}}
const match=path.match(/artifacts\.(\d+)\.(.*)$/);if(match){const a=char().artifacts[+match[1]],copy=structuredClone(a),keys=match[2].split('.');let obj=copy;for(const k of keys.slice(0,-1))obj=obj[k];obj[keys.at(-1)]=v;if(['rarity','level','main.stat'].includes(match[2]))applyMain(copy,+match[1]);if(match[2].startsWith('subs.')){const j=+keys[1];if(keys[2]==='stat')copy.subs[j].value=0;const problems=artifactIssues(copy,+match[1]);if(problems.length&&keys[2]==='value'&&v>0){toast(problems[0]);render();return}}char().artifacts[+match[1]]=copy;}else setPath(path,v);persist();render()}else if(el.dataset.check){setPath(el.dataset.check,el.checked);persist();render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mainTable!==undefined){applyMain(char().artifacts[+b.dataset.mainTable],+b.dataset.mainTable)}else if(b.dataset.clearSub){const [i,j]=b.dataset.clearSub.split(',').map(Number);char().artifacts[i].subs[j].value=0}else if(b.dataset.addRoll){const [i,j,k]=b.dataset.addRoll.split(',').map(Number);const a=char().artifacts[i];a.slot=slots[i];if(!addRoll(a,j,k))toast('Cannot add this roll. Check duplicate stats, existing totals and the level’s roll budget.')}else if(b.dataset.energyRemove!==undefined){team().energyEvents.splice(+b.dataset.energyRemove,1)}else if(b.dataset.battle!==undefined){state.selected=+b.dataset.battle;state.member=0}else if(b.dataset.member!==undefined)state.member=+b.dataset.member;else if(b.dataset.tab)state.tab=b.dataset.tab;else if(b.dataset.removeBuff!==undefined)team().buffs.splice(+b.dataset.removeBuff,1);else if(b.dataset.removeAction!==undefined)char().actions.splice(+b.dataset.removeAction,1);else{const c=char(),t=team();switch(b.dataset.do){case 'energyadd':(t.energyEvents??=[]).push({kind:'particle',element:c.element,count:0,catcher:state.member,source:state.member,target:'all',enabled:true});break;case 'bossapply':applyBoss();break;case 'bossrefresh':loadBosses();return;case 'buffadd':t.buffs.push(buff('Custom effect','atkPct',0));break;case 'buffoff':t.buffs.forEach(x=>x.enabled=false);break;case 'actionadd':c.actions.push({name:'New attack',mode:'normal',scaling:'atk',mult:100,hits:1,flat:0,bonus:0,reactionBonus:0});break;case 'snapshot':state.snapshot={battle:state.selected,name:c.name,damage:calc(t).total,team:structuredClone(t)};toast('Comparison baseline saved. Edit your build to see the difference.');break;case 'restore':if(state.snapshot){state.selected=state.snapshot.battle;state.teams[state.selected]=structuredClone(state.snapshot.team);state.member=0;toast('Saved battle restored.')}break;case 'alternate':{const toSucrose=c.name!=='Sucrose';const name=toSucrose?'Sucrose':state.selected===0?'Faruzan':'Qiqi';t.chars[3]=character(name,toSucrose||state.selected===0?'Anemo':'Cryo',toSucrose||state.selected===0?6:1,toSucrose?(state.selected===0?'Sacrificial Fragments':'Thrilling Tales of Dragon Slayers'):state.selected===0?'Favonius Warbow':'Favonius Sword',toSucrose||state.selected===0?5:1,toSucrose||state.selected===0?'Viridescent Venerer':'Tenacity of the Millelith');t.buffs.forEach(x=>x.enabled=false);if(toSucrose&&!t.buffs.some(x=>x.label.includes('Sucrose EM')))t.buffs.push(buff('Sucrose EM share (enter actual value)','em',0),buff('TTDS ATK (R5; recipient only)','atkPct',48,'0'));toast('Teammate switched. Review stats and re-enable eligible buffs.');break}case 'weapon':if(!weapons[c.weapon]){toast('No verified preset for this weapon. Enter its in-game stats.');return}[c.weaponAtk,c.weaponStat,c.weaponValue]=weapons[c.weapon];c.weaponLevel=90;toast('Loaded level-90 secondary stat and base ATK. Passives remain manual.');break;case 'echoes':c.weapon='Echoes of the Heart';[c.weaponAtk,c.weaponStat,c.weaponValue]=weapons[c.weapon];c.weaponLevel=90;toast('Echoes equipped. Review its passive in Team buffs.');break;case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='stygian-builds.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Builds exported.');return}case 'import':importBuild();return;case 'reset':if(!confirm('Reset all three teams and the saved comparison? Export first to keep a backup.'))return;{const saved=state.savedTeams||[];state=defaults();state.savedTeams=saved;}toast('Original presets restored. Saved teams kept.');break;default:return}}persist();render()});
function validateImport(s){if(!s||s.version!==1||!Array.isArray(s.teams)||s.teams.length!==3)throw Error('Expected a Stygian Lab export with three teams.');function inspect(v){if(typeof v==='number'&&(!Number.isFinite(v)||Math.abs(v)>1e12))throw Error('Invalid numeric input.');if(typeof v==='string'&&v.length>4000)throw Error('Text value too long.');if(v&&typeof v==='object')for(const [k,x]of Object.entries(v)){if(['__proto__','prototype','constructor'].includes(k))throw Error('Invalid data key.');inspect(x)}}inspect(s);const template=defaults().teams[0];function shape(value,model){if(Array.isArray(model)){if(!Array.isArray(value))throw Error('Invalid list.');for(const x of value)shape(x,model[0]);return}if(model&&typeof model==='object'){if(!value||typeof value!=='object')throw Error('Missing object.');for(const [k,x]of Object.entries(model))shape(value[k],x);return}if(typeof value!==typeof model)throw Error('Missing or invalid field.')}for(const t of s.teams){shape(t,template);for(const b of t.buffs)if(!Object.hasOwn(buffNames,b.stat)||!['all','0','1','2','3'].includes(String(b.target))||b.uptime<0||b.uptime>100)throw Error('Invalid buff.');if(!Array.isArray(t.chars)||t.chars.length!==4||!Array.isArray(t.buffs)||t.buffs.length>150||!(t.rotation>=1)||!(t.hp>0)||t.downtime<0)throw Error('Invalid team structure.');for(const c of t.chars){if(c.setMode!==undefined&&!['four','split'].includes(c.setMode))throw Error('Invalid set configuration.');if(c.set2!==undefined&&typeof c.set2!=='string')throw Error('Invalid second set.');if(!Array.isArray(c.artifacts)||c.artifacts.length!==5||!Array.isArray(c.actions)||c.actions.length>100||c.level<1||c.level>100||c.cons<0||c.cons>6||c.refine<1||c.refine>5)throw Error('Invalid character structure.');for(const a of c.artifacts){if(!a.main||!Array.isArray(a.subs)||a.subs.length!==4||![a.main,...a.subs].every(x=>Object.hasOwn(statNames,x.stat)&&typeof x.value==='number'&&x.value>=0))throw Error('Invalid artifact stats.')}for(const a of c.actions)if(!Object.hasOwn(modes,a.mode)||!['atk','hp','def','em'].includes(a.scaling)||a.hits<0||a.mult<0)throw Error('Invalid attack data.')}if(!Number.isFinite(calc(t).total))throw Error('Incomplete numeric data.')}if(s.savedTeams!==undefined){if(!Array.isArray(s.savedTeams)||s.savedTeams.length>200)throw Error('Invalid saved team library.');const ids=new Set();for(const x of s.savedTeams){if(!x||typeof x.id!=='string'||ids.has(x.id)||typeof x.name!=='string'||!x.name.trim()||typeof x.updatedAt!=='string'||!Number.isFinite(Date.parse(x.updatedAt)))throw Error('Invalid saved team record.');ids.add(x.id);validateImport({version:1,teams:[x.team,x.team,x.team],goal:218});}}s.selected=0;s.member=0;s.tab='build';s.snapshot=null;if(!(s.goal>0))s.goal=218;return s}
function importBuild(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2e6)throw Error('File is too large.');const next=validateImport(JSON.parse(await file.text()));state=next;persist();render();toast('Builds and saved team library imported successfully.')}catch(e){toast('Import failed: '+e.message)}};input.click()}

let bossData=null,bossLoading=false;async function loadBosses(){if(bossData||bossLoading)return;bossLoading=true;try{const res=await fetch('./stygian-bosses.json');if(!res.ok)throw Error();bossData=await res.json();bossLoading=false;render()}catch{bossLoading=false;toast('Could not load the bundled Stygian boss list.')}}
function bossPanel(){if(!bossData){loadBosses();return `<div class="panel"><h3>Stygian Onslaught bosses</h3><p>Loading verified ${esc(bossData?.version||'7.1')} boss data…</p></div>`}const t=team(),boss=bossData.bosses.find(x=>x.id===t.bossId)||bossData.bosses[0],phase=boss.phases.find(x=>x.name===t.bossPhase)||boss.phases[0];return `<div class="panel"><h3>Stygian Onslaught · version ${esc(bossData.version)}</h3><p>Season ${esc(bossData.start)} to ${esc(bossData.end)} · Data checked ${esc(bossData.verified)} · <a href="${esc(bossData.source)}" target="_blank" rel="noopener">Stygian.moe ↗</a></p><div class="grid"><label class="field">Boss<select id="boss-id">${bossData.bosses.map(b=>`<option value="${esc(b.id)}" ${b.id===boss.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label class="field">Phase / damage window<select id="boss-phase">${boss.phases.map(x=>`<option value="${esc(x.name)}" ${x.name===phase.name?'selected':''}>${esc(x.name)} · ${x.res}% RES</option>`).join('')}</select></label><label class="field">Difficulty / enemy level<select id="boss-level"><option value="105" ${t.enemyLevel<=105?'selected':''}>N5 · Level 105</option><option value="110" ${t.enemyLevel>105?'selected':''}>N6 · Level 110</option></select></label></div><p>${esc(boss.note)}</p><button data-do="bossapply">Apply boss HP, level & selected-phase resistance</button><p class="inline-note">Phase is a manual snapshot. Shield checks, stacks, scripted transitions and damage windows still need player input. N5/N6 HP values from public boss guide.</p></div>`}
function applyBoss(){const id=$('#boss-id')?.value,phaseName=$('#boss-phase')?.value,level=Number($('#boss-level')?.value),boss=bossData?.bosses.find(x=>x.id===id);if(!boss)return;team().bossId=id;team().bossPhase=phaseName;team().enemyLevel=level;team().hp=boss.hp[String(level)]||boss.hp['105'];team().res=boss.phases.find(x=>x.name===phaseName)?.res??10;persist();render();toast('Boss assumptions applied. Verify phase and energy drops for your rotation.')}
function energyPanel(){const t=team();t.energyEvents??=[];const budgets=energyBudget(t,c=>effective(c,t,t.chars.indexOf(c)).s);const event=(label,kind,element='all')=>`<button data-energy-add="${kind}" data-element="${element}">${label}</button>`;return `<div class="panel"><h3>Opening energy · zero-start encounter</h3><p>All four characters begin at 0 Energy. Enter only particles, orbs, Favonius triggers and flat-energy effects that your opening rotation actually generates. Catcher selects who is on field for the event; other party members are estimated off-field. Burst cooldowns and event timing are not simulated.</p><div class="energy-cards">${budgets.map((b,i)=>`<div class="energy-card"><strong>${esc(t.chars[i].name)}</strong><span>${num(b.energy,1)} / ${b.cost?num(b.required,1):'burst cost unknown'} energy</span>${b.cost?`<div class="bar"><i style="width:${Math.min(100,b.energy/b.required*100)}%"></i></div><small>${b.deficit?num(b.deficit,1)+' energy short':'Opening bursts covered by entered events'}</small>`:`<small>${b.special?'Uses a special resource; set Burst cost to track manually.':'Enter the character’s burst cost in Character & weapon.'}</small>`}</div>`).join('')}</div></div><div class="panel"><h3>Add an opening energy event</h3><div class="energy-buttons">${event('Favonius proc · 3 clear particles','fav')}${event('Skill particles','particle')}${event('Boss elemental particles','bossParticle')}${event('Boss elemental orb','bossOrb')}${event('Boss clear particles','clear')}${event('Boss clear orb','clearOrb')}${event('Flat energy','flat')}</div><p class="inline-note">Favonius only generates particles when its passive procs (including its CRIT and cooldown conditions). Refinement changes proc chance, not the three-particle amount. Boss drops must be entered per boss and phase; shield hits may trigger Favonius.</p><div class="grid">${t.chars.map((c,i)=>field(`${esc(c.name)} burst cost`,tp(`chars.${i}.burstCost`),c.burstCost??0,{min:0,max:100,step:1})).join('')}</div>${t.energyEvents.map((e,i)=>`<div class="energy-event"><strong>${esc(({fav:'Favonius proc · 3 clear particles',particle:'Skill particles',bossParticle:'Boss elemental particles',bossOrb:'Boss elemental orb',clear:'Clear particles',clearOrb:'Clear orb',flat:'Flat energy'})[e.kind]||'Energy event')}</strong><div class="grid">${field('Count',tp(`energyEvents.${i}.count`),e.count,{min:0,max:100,step:1})}${field('Element',tp(`energyEvents.${i}.element`),e.element||'clear',{options:{clear:'Clear',Anemo:'Anemo',Cryo:'Cryo',Dendro:'Dendro',Electro:'Electro',Geo:'Geo',Hydro:'Hydro',Pyro:'Pyro'}})}${field('On-field catcher',tp(`energyEvents.${i}.catcher`),e.catcher??0,{options:Object.fromEntries(t.chars.map((c,j)=>[j,c.name]))})}${e.kind==='fav'?field('Favonius holder',tp(`energyEvents.${i}.source`),e.source??0,{options:Object.fromEntries(t.chars.map((c,j)=>[j,c.name]))}):''}<button data-energy-remove="${i}" aria-label="Remove energy event">Remove</button></div></div>`).join('')||'<p class="empty">No energy events yet. Start with a Favonius trigger or particles that your opening skills produce.</p>'}</div><div class="panel"><h3>Energy assumptions</h3><p>Favonius creates 3 clear particles on a valid proc; each party member’s gain depends on being the catcher, party position and their Energy Recharge. Boss HP-threshold drops can differ by boss. The estimator checks totals only and will not claim a burst is available before its event arrives.</p><a class="source" href="https://library.keqingmains.com/combat-mechanics/energy" target="_blank" rel="noopener">KQM · Energy particle values ↗</a></div>`}
document.addEventListener('change',e=>{if(e.target.id==='boss-id'){const b=bossData?.bosses.find(x=>x.id===e.target.value);const sel=$('#boss-phase');if(sel)sel.innerHTML=b.phases.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} · ${x.res}% RES</option>`).join('')}if(e.target.dataset.path?.includes('burstCost')||e.target.closest('.energy-event')){const path=e.target.dataset.path;if(path){let v=e.target.type==='number'?Number(e.target.value):e.target.value;setPath(path,v);persist();render()}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-energy-add]');if(!b)return;const kind=b.dataset.energyAdd;team().energyEvents??=[];team().energyEvents.push({kind,count:kind==='fav'?1:kind==='flat'?0:1,element:b.dataset.element||char().element,catcher:state.member,source:state.member,enabled:true});persist();render()});

setupBuilder({calc,state:()=>state,team,character:char,member:()=>state.member,normalize:normalizeName,resolve:resolveName,localImage:(kind,name)=>findMedia(kind,name)?.image,persist,render,toast,choose:(kind,item,slot)=>{const t=team(),c=char();if(kind==='characters'){const starter={Sword:'Favonius Sword',Claymore:"Wolf’s Gravestone",Polearm:'Favonius Lance',Bow:'Favonius Warbow',Catalyst:'Favonius Codex'};const next=character(item.name,item.element||'Anemo',0,starter[item.weaponType]||'',1,'Gladiator’s Finale');if(weapons[next.weapon])[next.weaponAtk,next.weaponStat,next.weaponValue]=weapons[next.weapon];next.notes='New character: example base stats and attack coefficients. Configure your actual build.';t.chars[state.member]=next;t.subtitle=t.chars.map(x=>x.name).join(' · ');t.buffs.forEach(x=>x.enabled=false);toast('Character changed. Configure stats, attacks and eligible buffs.')}else if(kind==='weapons'){c.weapon=item.name;c.weaponLevel=90;if(weapons[item.name]||weapons[item.name.replace(/'/g,'’')])[c.weaponAtk,c.weaponStat,c.weaponValue]=weapons[item.name]||weapons[item.name.replace(/'/g,'’')];else{c.weaponAtk=0;c.weaponStat='atkPct';c.weaponValue=0;}t.buffs.forEach(x=>x.enabled=false);toast('Weapon equipped. Review base stats, refinement and passives.')}else{c[slot]=item.name;t.buffs.forEach(x=>x.enabled=false);toast('Artifact set equipped. Review active set buffs.')}persist();render()}});
